.wf-catalog{--wf-accent:var(--wf-color-primary,#12b8a6);--wf-panel:var(--wf-color-surface,#fff);--wf-border:var(--wf-color-border,#dbe4ea);--wf-text:var(--wf-color-text,#102230);--wf-muted:var(--wf-color-muted,#647482);box-sizing:border-box;max-width:1440px;margin:0 auto;padding:clamp(1rem,3vw,2.5rem);color:var(--wf-text);font-family:Inter,system-ui,sans-serif}.wf-catalog *{box-sizing:border-box}.wf-catalog__header{display:flex;align-items:flex-end;justify-content:space-between;gap:1rem;margin-bottom:1.25rem}.wf-catalog__header h1{margin:.2rem 0;font-size:clamp(1.8rem,4vw,3rem);line-height:1.05}.wf-catalog__eyebrow{margin:0;color:var(--wf-accent);font-size:.78rem;font-weight:800;letter-spacing:.16em;text-transform:uppercase}.wf-catalog__count,.wf-catalog__status{margin:.35rem 0 0;color:var(--wf-muted)}.wf-catalog__toolbar{display:grid;grid-template-columns:minmax(14rem,1fr) minmax(11rem,auto) minmax(11rem,auto) auto;gap:.75rem;padding:1rem;background:var(--wf-color-secondary,#f5f8fa);border:1px solid var(--wf-border);border-radius:1rem}.wf-catalog input,.wf-catalog select,.wf-catalog button{min-height:2.75rem;border:1px solid var(--wf-border);border-radius:.7rem;background:var(--wf-panel);color:var(--wf-text);font:inherit}.wf-catalog input,.wf-catalog select{width:100%;padding:.65rem .8rem}.wf-catalog button{padding:.6rem 1rem;font-weight:750;cursor:pointer}.wf-catalog__toolbar>button,.wf-catalog__pagination :is(button,a)[aria-current=true]{border-color:var(--wf-accent);background:var(--wf-accent);color:var(--wf-color-on-primary,#062d29)}.wf-catalog__view{display:flex;gap:.4rem}.wf-catalog__view button{min-width:2.75rem;padding:.4rem}.wf-catalog__view button[aria-pressed=true]{border-color:var(--wf-accent);box-shadow:0 0 0 2px var(--wf-border)}.wf-catalog__body{display:grid;grid-template-columns:minmax(13rem,17rem) minmax(0,1fr);gap:1.5rem;margin-top:1.5rem}.wf-catalog__filters{display:grid;align-content:start;gap:.75rem}.wf-catalog__filter{border:1px solid var(--wf-border);border-radius:.85rem;background:var(--wf-panel);padding:.85rem}.wf-catalog__filter summary{cursor:pointer;font-weight:800}.wf-catalog__filter-count{color:var(--wf-muted);font-weight:700}.wf-catalog__filter-list{display:grid;gap:.55rem;margin-top:.75rem}.wf-catalog__filter label{display:flex;align-items:flex-start;gap:.55rem;font-size:.9rem}.wf-catalog__filter input{width:1rem;min-height:1rem;margin-top:.15rem}.wf-catalog__filter small{margin-left:auto;color:var(--wf-muted)}.wf-catalog__results{display:grid;grid-template-columns:repeat(var(--wf-cols-desktop),minmax(0,1fr));gap:1rem}.wf-product{display:flex;min-width:0;flex-direction:column;overflow:hidden;border:1px solid var(--wf-border);border-radius:1rem;background:var(--wf-panel);box-shadow:0 6px 22px rgba(16,34,48,.06)}.wf-product__link{display:flex;flex:1;flex-direction:column;min-width:0;color:inherit;text-decoration:none}.wf-product__media{display:block;aspect-ratio:1/1;background:var(--wf-color-secondary,#f1f4f6);overflow:hidden}.wf-catalog[data-image-ratio="1/1"] .wf-product__media{aspect-ratio:1/1}.wf-catalog[data-image-ratio="4/3"] .wf-product__media{aspect-ratio:4/3}.wf-catalog[data-image-ratio="3/4"] .wf-product__media{aspect-ratio:3/4}.wf-product__media img{width:100%;height:100%;object-fit:contain;transition:transform .2s ease}.wf-product:hover .wf-product__media img{transform:scale(1.03)}.wf-product__content{display:flex;flex:1;flex-direction:column;padding:1rem}.wf-product__meta{margin:0 0 .35rem;color:var(--wf-muted);font-size:.77rem;text-transform:uppercase;letter-spacing:.05em}.wf-product h2{margin:0;font-size:1rem;line-height:1.35}.wf-product__footer{display:flex;align-items:flex-end;justify-content:space-between;gap:.5rem;margin-top:auto;padding-top:1rem}.wf-product__price{font-size:1.08rem;font-weight:850}.wf-product__stock{color:#197149;font-size:.78rem}.wf-product__stock[data-empty=true]{color:#a63d3d}.wf-catalog[data-layout=list] .wf-catalog__results{grid-template-columns:1fr}.wf-catalog[data-layout=list] .wf-product{display:block}.wf-catalog[data-layout=list] .wf-product__link{display:grid;grid-template-columns:minmax(9rem,15rem) 1fr;height:100%}.wf-catalog[data-layout=list] .wf-product__media{height:100%}.wf-catalog__empty{grid-column:1/-1;padding:3rem 1rem;text-align:center;border:1px dashed var(--wf-border);border-radius:1rem;color:var(--wf-muted)}.wf-catalog__pagination{display:flex;justify-content:center;flex-wrap:wrap;gap:.45rem;margin-top:1.5rem}.wf-catalog__pagination :is(button,a):disabled{opacity:.45;cursor:not-allowed}.wf-catalog__status[data-error=true]{padding:.75rem;border-radius:.65rem;background:#fff2f2;color:#a12626}.wf-visually-hidden{position:absolute!important;width:1px!important;height:1px!important;padding:0!important;margin:-1px!important;overflow:hidden!important;clip:rect(0,0,0,0)!important;white-space:nowrap!important;border:0!important}@media(max-width:960px){.wf-catalog__results{grid-template-columns:repeat(var(--wf-cols-tablet),minmax(0,1fr))}.wf-catalog__toolbar{grid-template-columns:1fr 1fr}.wf-catalog__search{grid-column:1/-1}.wf-catalog__body{grid-template-columns:1fr}.wf-catalog__filters{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.wf-catalog{padding:1rem}.wf-catalog__header{align-items:flex-start}.wf-catalog__toolbar{grid-template-columns:1fr}.wf-catalog__search{grid-column:auto}.wf-catalog__filters{grid-template-columns:1fr}.wf-catalog__results{grid-template-columns:repeat(var(--wf-cols-mobile),minmax(0,1fr))}.wf-catalog[data-layout=list] .wf-product__link{grid-template-columns:7rem 1fr}.wf-catalog__view{display:none}}.wf-catalog__results{min-height:12rem}.wf-catalog__chips{display:flex;flex-wrap:wrap;gap:.5rem;align-items:center;margin-top:1rem}.wf-catalog__chips button{min-height:2.25rem;border-radius:999px}.wf-catalog__filters-toggle{display:none}@media(max-width:960px){.wf-catalog__filters-toggle{display:inline-flex}.wf-catalog[data-filters-open="false"] .wf-catalog__filters,.wf-catalog:not([data-filters-open]) .wf-catalog__filters{display:none}.wf-catalog[data-filters-open="true"] .wf-catalog__filters{display:grid}}
.wf-catalog__pagination a{display:inline-flex;align-items:center;justify-content:center;min-height:2.75rem;min-width:2.75rem;padding:.6rem 1rem;border:1px solid var(--wf-border);border-radius:.7rem;color:var(--wf-text);text-decoration:none;font-weight:750}.wf-catalog__pagination [aria-current=page]{background:var(--wf-accent);border-color:var(--wf-accent);color:var(--wf-color-on-primary,#062d29)}.wf-catalog__pagination [aria-disabled=true]{display:inline-flex;align-items:center;padding:.6rem;opacity:.5}.wf-catalog__range{display:grid;grid-template-columns:1fr 1fr;gap:.4rem}.wf-catalog__range button{grid-column:1/-1}.wf-product__prices{display:flex;flex-direction:column;align-items:flex-start;gap:.15rem}.wf-product__prices del{color:var(--wf-muted);font-size:.8rem}.wf-product__prices small{color:var(--wf-text);font-weight:700}.wf-catalog__offers-status{color:var(--wf-muted);font-size:.85rem}.wf-catalog [hidden]{display:none!important}
.wf-catalog__controls{display:flex;align-items:center;justify-content:flex-end;gap:.65rem;min-width:0;flex-wrap:wrap}
.wf-catalog__sort{min-width:10rem}.wf-catalog__toolbar{grid-template-columns:minmax(0,1fr) minmax(10rem,1fr) auto}
.wf-catalog[data-show-catalog-search="false"] .wf-catalog__search,.wf-catalog[data-show-catalog-search="false"] [data-wf-apply-search],.wf-catalog[data-show-category-select="false"] [data-wf-category-label]{display:none}
.wf-catalog[data-show-catalog-search="false"][data-show-category-select="false"] .wf-catalog__toolbar{display:none}
.wf-catalog__toolbar>label[hidden]{display:none}.wf-catalog__chips:empty,.wf-catalog__status:empty{display:none}
.wf-product__media{position:relative}.wf-product__badges{position:absolute;inset-block-start:.65rem;inset-inline-start:.65rem;display:flex;flex-direction:column;align-items:flex-start;gap:.3rem;pointer-events:none;max-width:calc(100% - 1.3rem)}
.wf-catalog[data-badge-position="top-end"] .wf-product__badges{inset-inline-start:auto;inset-inline-end:.65rem;align-items:flex-end}
.wf-product__badge{display:inline-block;max-width:100%;padding:.3rem .55rem;border-radius:.4rem;background:var(--wf-panel);color:var(--wf-text);border:1px solid var(--wf-border);font-size:.78rem;font-weight:800;line-height:1.2;overflow-wrap:anywhere}
.wf-product__badge--discount{background:var(--wf-accent);color:var(--wf-color-on-primary,#062d29);border-color:var(--wf-accent)}
.wf-product__prices{display:grid;grid-template-rows:1.1rem minmax(1.5rem,auto);gap:.15rem;align-content:end}.wf-product__prices>del{grid-row:1}.wf-product__prices>[data-wf-price]{grid-row:2}
.wf-catalog[data-show-regular-price="false"] .wf-product__prices{grid-template-rows:minmax(1.5rem,auto)}.wf-catalog[data-show-regular-price="false"] .wf-product__prices>[data-wf-price]{grid-row:1}
.wf-product__stock{display:block;min-height:2.4em;line-height:1.2;max-width:8rem;text-align:end}.wf-product__description{display:none;margin:.75rem 0 0;color:var(--wf-muted);font-size:.9rem;line-height:1.5}
.wf-catalog[data-layout="list"] .wf-product__description{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:3;overflow:hidden}
.wf-catalog__range{display:grid;grid-template-columns:minmax(0,1fr);gap:.75rem;min-width:0}.wf-catalog__range-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.5rem}
.wf-catalog__range-fields label{display:grid;min-width:0;gap:.25rem}.wf-catalog__filter .wf-catalog__range-fields input{width:100%;min-width:0;min-height:2.75rem;margin:0;padding:.5rem}.wf-catalog__range-fields button{grid-column:1/-1}
.wf-catalog__range-sliders{position:relative;height:2.75rem;background:linear-gradient(to right,var(--wf-border) var(--wf-range-start,0%),var(--wf-accent) var(--wf-range-start,0%),var(--wf-accent) var(--wf-range-end,100%),var(--wf-border) var(--wf-range-end,100%)) center/100% 4px no-repeat}
.wf-catalog__filter .wf-catalog__range-sliders input{appearance:none;-webkit-appearance:none;position:absolute;inset:0;width:100%;height:2.75rem;min-height:2.75rem;margin:0;padding:0;pointer-events:none;background:transparent;border:0}
.wf-catalog__range-sliders input::-webkit-slider-thumb{-webkit-appearance:none;pointer-events:auto;width:1.4rem;height:1.4rem;border:2px solid var(--wf-panel);border-radius:50%;background:var(--wf-accent);box-shadow:0 0 0 1px var(--wf-accent);cursor:grab}
.wf-catalog__range-sliders input::-moz-range-thumb{pointer-events:auto;width:1.4rem;height:1.4rem;border:2px solid var(--wf-panel);border-radius:50%;background:var(--wf-accent);cursor:grab}
.wf-catalog__range-sliders input:focus-visible{outline:2px solid var(--wf-text);outline-offset:3px}.wf-catalog__range-fields input[aria-invalid="true"]{outline:2px solid #a12626}
.wf-catalog[data-price-filter-mode="inputs"] [data-wf-range-sliders],.wf-catalog[data-price-filter-mode="slider"] [data-wf-range-fields]{display:none}
@media(max-width:600px){.wf-catalog__header{flex-wrap:wrap;gap:.75rem}.wf-catalog__controls{width:100%;justify-content:space-between}.wf-catalog__view{display:flex}.wf-catalog__sort{flex:1}.wf-catalog[data-layout="list"] .wf-product__link{grid-template-columns:minmax(6rem,30%) minmax(0,1fr)}.wf-product__content{padding:.75rem}.wf-product__footer{flex-wrap:wrap}.wf-product__stock{text-align:start}}
@media(prefers-reduced-motion:reduce){.wf-product__media img{transition:none}.wf-product:hover .wf-product__media img{transform:none}}

.wf-catalog[data-show-price="false"] .wf-product__prices{display:none}

/* Stable catalog presentation v2. The overlay never contributes to layout. */
.wf-catalog { scroll-margin-top:100px; }
.wf-catalog__main { position:relative; min-width:0; }
.wf-catalog__loading { display:none; position:absolute; inset:0; z-index:4; background:color-mix(in srgb,var(--wf-bg,#fff) 72%,transparent); cursor:progress; }
.wf-catalog[data-wf-busy="true"] .wf-catalog__loading { display:block; }
.wf-catalog__loading span { display:block; position:sticky; top:120px; margin:50px auto; width:28px; height:28px; border:3px solid #ddd; border-top-color:var(--wf-accent,#ff9800); border-radius:50%; animation:wf-catalog-spin .8s linear infinite; }
@keyframes wf-catalog-spin { to { transform:rotate(360deg); } }
@media(prefers-reduced-motion:reduce){ .wf-catalog__loading span { animation:none; } }
.wf-catalog__status:empty { display:none; }
.wf-catalog__range-labels { display:flex; justify-content:space-between; gap:8px; font-size:12px; font-variant-numeric:tabular-nums; }
.wf-catalog__range-manual { margin-top:10px; }
.wf-catalog__range-manual>summary { cursor:pointer; font-size:12px; padding:4px 0; }
.wf-catalog[data-price-filter-mode="slider-popover"] .wf-catalog__range-manual:not([open])>[data-wf-range-fields] { display:none; }
.wf-catalog:not([data-price-filter-mode="slider-popover"]) .wf-catalog__range-manual>summary { display:none; }
.wf-catalog:not([data-price-filter-mode="slider-popover"]) .wf-catalog__range-manual>[data-wf-range-fields] { display:grid; }
.wf-catalog[data-price-filter-mode="slider"] .wf-catalog__range-manual { display:none; }
.wf-catalog[data-price-filter-mode="inputs"] .wf-catalog__range-labels { display:none; }
.wf-product__stock { display:flex; align-items:center; gap:5px; min-height:2.5em; max-width:170px; }
.wf-stock__truck { flex:0 0 18px; width:18px; height:18px; }

.wf-product__stock { flex:0 0 76px; max-width:76px; min-height:36px; line-height:16px; justify-content:flex-end; }

.wf-product { container-type:inline-size; }
@container (max-width:220px) { .wf-product__footer { flex-direction:column; align-items:stretch; gap:0; } .wf-product__stock { flex-basis:auto; max-width:none; justify-content:flex-start; } }

.wf-shop,.wf-shop-actions,.wf-shop-shell{--shop-accent:var(--wf-color-primary,#ff9800);--shop-text:var(--wf-color-text,#222526);--shop-muted:var(--wf-color-muted,#626a70);--shop-border:var(--wf-color-border,#e0e4e7);--shop-surface:var(--wf-color-surface,#fff);color:var(--shop-text);font-family:inherit;box-sizing:border-box}
.wf-shop *,.wf-shop-actions *,.wf-shop-shell *{box-sizing:border-box}
.wf-shop{max-width:1160px;padding:32px 24px 64px;margin:0 auto;min-height:45vh}
.wf-shop h1{font-size:clamp(26px,4vw,36px);line-height:1.15;margin:0 0 24px;font-weight:800;letter-spacing:-.025em}
.wf-shop h2{font-size:21px;margin:24px 0 16px}.wf-shop [hidden],.wf-shop-actions [hidden],.wf-shop-shell [hidden]{display:none!important}
.wf-shop-btn,.wf-shop-heart,.wf-shop-link{font:inherit;cursor:pointer;min-height:42px;border-radius:8px;transition:background-color .15s}
.wf-shop-btn{display:inline-flex;align-items:center;justify-content:center;padding:10px 17px;font-weight:750;text-decoration:none;background:var(--shop-accent);border:1px solid transparent;color:var(--wf-shop-on-accent,#171a1c);line-height:1.3}
.wf-shop-btn:hover{filter:brightness(.96)}.wf-shop-btn:disabled{background:#edf0f2;color:#778189;cursor:default;filter:none}.wf-shop-btn:focus-visible,.wf-shop-heart:focus-visible,.wf-shop input:focus-visible,.wf-shop select:focus-visible,.wf-shop-actions input:focus-visible{outline:2px solid var(--shop-accent);outline-offset:3px}
.wf-shop-link{border:0;background:transparent;color:var(--shop-muted);padding:6px 8px;text-decoration:underline;text-underline-offset:3px;font-size:13px}
.wf-shop-shell{display:flex;align-items:center;gap:5px}.wf-shop-shell a{display:inline-flex;align-items:center;gap:6px;padding:9px;color:inherit;text-decoration:none;border-radius:8px;min-height:42px;white-space:nowrap}.wf-shop-shell a:hover{background:var(--wf-color-secondary,#f4f5f6)}
.wf-shop-shell svg,.wf-shop-heart svg{width:21px;height:21px;flex:none}.wf-shop-shell [data-wf-cart-count]{font-size:11px;line-height:18px;min-width:18px;text-align:center;background:var(--shop-text);color:var(--shop-surface);border-radius:9px;font-variant-numeric:tabular-nums}
.wf-shop-actions{padding:10px 12px 12px;border-top:1px solid var(--shop-border);min-height:65px}.wf-detail [data-wf-shop-actions]{padding:16px 0;margin-top:12px}.wf-shop-actions__row{display:flex;align-items:center;gap:6px;flex-wrap:wrap}.wf-shop-actions .wf-shop-btn{flex:1;font-size:13px;padding:9px 10px;min-width:115px}.wf-shop-qty{width:62px;min-width:0;min-height:42px;border:1px solid var(--shop-border);border-radius:8px;background:var(--shop-surface);color:var(--shop-text);font:inherit;padding:8px 5px;text-align:center;font-variant-numeric:tabular-nums}.wf-shop-unit{font-size:12px;color:var(--shop-muted)}
.wf-shop-actions[data-wf-variants=true]{min-height:115px}.wf-product:has(.wf-shop-actions)>.wf-product__link{height:auto;flex:1}
.wf-product:has(.wf-shop-actions){position:relative}.wf-product .wf-shop-heart{position:absolute;top:10px;right:10px;z-index:2;box-shadow:0 1px 4px #0001}.wf-catalog[data-badge-position=top-end] .wf-product .wf-shop-heart{left:10px;right:auto}.wf-shop-actions .wf-shop-qty{width:56px}.wf-product .wf-shop-btn{min-width:105px;font-size:12px}.wf-shop-unit{white-space:nowrap}
.wf-shop-heart{display:inline-flex;align-items:center;justify-content:center;flex:none;width:42px;border:1px solid var(--shop-border);background:var(--shop-surface);color:var(--shop-muted)}.wf-shop-heart[aria-pressed=true]{color:#b52737;background:#fff5f6}.wf-shop-heart[aria-pressed=true] svg{fill:currentColor}
.wf-shop-variant{width:100%;margin-bottom:8px;padding:10px;border:1px solid var(--shop-border);border-radius:8px;font:inherit;background:var(--shop-surface);color:var(--shop-text)}
.wf-shop-lines{border-top:1px solid var(--shop-border);margin-bottom:24px}.wf-shop-line{display:flex;align-items:center;gap:18px;padding:20px 0;border-bottom:1px solid var(--shop-border);min-width:0}.wf-shop-line img{width:88px;height:88px;object-fit:cover;border-radius:10px;background:#f5f6f7}.wf-shop-line__body{display:flex;flex:1;flex-direction:column;gap:7px;min-width:0}.wf-shop-line a{color:var(--shop-text);font-weight:750;text-decoration:none}.wf-shop-line a:hover{text-decoration:underline}.wf-shop-line small{color:var(--shop-muted);font-size:12px}.wf-shop-line__controls{display:flex;align-items:center;gap:8px;flex-wrap:wrap;justify-content:flex-end}.wf-shop-line__controls strong{display:block;min-width:100px;text-align:right;font-variant-numeric:tabular-nums}.wf-shop-line__controls .wf-shop-qty{width:78px}
.wf-shop-totals{width:min(100%,370px);margin-left:auto;border-top:1px solid var(--shop-border);padding-top:12px}.wf-shop-totals>div{display:flex;justify-content:space-between;gap:20px;padding:7px 0;font-variant-numeric:tabular-nums}.wf-shop-totals>div:last-child{font-size:21px;font-weight:800;padding-top:16px;border-top:1px solid var(--shop-border);margin-top:6px}.wf-shop-help{font-size:13px;color:var(--shop-muted);line-height:1.5}.wf-shop-empty{padding:32px 0;color:var(--shop-muted)}
.wf-shop-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;max-width:800px}.wf-shop-field{display:flex;flex-direction:column;gap:7px;font-size:13px;color:var(--shop-muted)}.wf-shop-field input,.wf-shop-field select,.wf-shop-field textarea{width:100%;min-height:44px;border:1px solid var(--shop-border);border-radius:8px;background:var(--shop-surface);color:var(--shop-text);font:inherit;font-size:15px;padding:10px 12px}.wf-shop-field:has(textarea),.wf-shop-form>.wf-shop-btn,.wf-shop-form>.wf-shop-error{grid-column:1/-1}.wf-shop-field textarea{min-height:96px;resize:vertical}.wf-shop-address{grid-column:1/-1;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.wf-shop-form>.wf-shop-btn{justify-self:start}.wf-shop-error{color:#a12626;font-size:14px;margin:0}.wf-shop-error:empty{display:none}.wf-shop-preview{background:#fff8ea;border:1px solid #f0d49e;color:#694711;padding:12px 16px;border-radius:8px;font-size:14px;line-height:1.5}.wf-shop-review{max-width:900px}.wf-shop-notice{position:fixed;z-index:10000;bottom:24px;left:50%;transform:translateX(-50%);max-width:calc(100% - 32px);background:#23312a;color:#fff;border-radius:10px;padding:13px 20px;box-shadow:0 4px 20px #0002;font:14px/1.5 system-ui}.wf-shop-notice:empty{display:none}.wf-shop-notice[data-error=true]{background:#852e2e}
@media(max-width:700px){.wf-shop{padding:24px 16px 48px}.wf-shop-line{gap:12px;flex-wrap:wrap}.wf-shop-line img{width:65px;height:65px}.wf-shop-line__controls{width:100%;justify-content:flex-start;padding-left:77px}.wf-shop-line__controls strong{margin-left:auto}.wf-shop-form,.wf-shop-address{grid-template-columns:1fr}.wf-shop-form>.wf-shop-btn{width:100%}.wf-shop-shell a{padding:7px}.wf-shop-shell [data-wf-cart-label]{display:none}.wf-shop-actions{padding:10px}.wf-shop-actions .wf-shop-btn{min-width:120px}.wf-shop-notice{bottom:16px;width:max-content}}
@media(prefers-reduced-motion:reduce){.wf-shop-btn,.wf-shop-heart,.wf-shop-link{transition:none}}

